sql.where:
t.deleted = 0

    AND t.scenario_id = #{req.scenarioId}


    AND t.source_type = #{req.sourceType}


    AND t.source_no LIKE CONCAT('%', #{req.sourceNo}, '%')


    AND t.prod_order_id = #{req.prodOrderId}


    AND t.mat_id = #{req.matId}


    AND t.mat_code LIKE CONCAT('%', #{req.matCode}, '%')


    AND t.plant_id = #{req.plantId}


    AND t.workshop_id = #{req.workshopId}


    AND t.project_id = #{req.projectId}


    AND t.res_id = #{req.resId}


    AND t.current_status = #{req.currentStatus}


    AND t.locked_flag = #{req.lockedFlag}


    AND t.material_shortage_flag = #{req.materialShortageFlag}


    AND t.due_date BETWEEN #{req.dueDate[0]} AND #{req.dueDate[1]}


    AND t.snapshot_time BETWEEN #{req.snapshotTime[0]} AND #{req.snapshotTime[1]}
